nd lk(KB.DropBrainrot,cfg.dropBrainrotKey);lk(KB.AutoLeft,cfg.autoLeftKey);lk(KB.AutoRight,cfg.autoRightKey) lk(KB.AutoBat,cfg.autoBatKey);if cfg.batV2Key then lk(KB.BatV2,cfg.batV2Key) end lk(KB.LaggerToggle,cfg.laggerToggleKey) lk(KB.TPFloor,cfg.tpFloorKey);lk(KB.InstaReset,cfg.instaResetKey);lk(KB.GuiHide,cfg.guiHideKey);lk(KB.SpeedToggle,cfg.speedToggleKey) if cfg.normalSpeed then NS=cfg.normalSpeed end if cfg.carrySpeed then CS=cfg.carrySpeed end if cfg.laggerSpeed and type(cfg.laggerSpeed)=="number" then LAGGER_SPEED=cfg.laggerSpeed end if cfg.laggerCarrySpeed and type(cfg.laggerCarrySpeed)=="number" then LAGGER_CARRY_SPEED=cfg.laggerCarrySpeed end if cfg.stealDuration and type(cfg.stealDuration)=="number" then Steal.StealDuration=cfg.stealDuration else Steal.StealDuration=1.3 end if cfg.autoTPHeight and type(cfg.autoTPHeight)=="number" then autoTPHeight=cfg.autoTPHeight end if cfg.autoSwing~=nil then autoSwingEnabled=cfg.autoSwing==true end if cfg.antiDesync~=nil then antiDesyncEnabled=cfg.antiDesync==true end if cfg.infiniteJump~=nil then infJumpEnabled=cfg.infiniteJump==true end if cfg.uiLocked~=nil then uiLocked=cfg.uiLocked==true end if cfg.autoSwitchSpeed~=nil then autoSwitchSpeedEnabled=cfg.autoSwitchSpeed==true end if cfg.dropMode and (cfg.dropMode=="stand" or cfg.dropMode=="jump") then dropMode=cfg.dropMode end if cfg.stealMode and (cfg.stealMode=="normal" or cfg.stealMode=="semi") then stealMode=cfg.stealMode end if cfg.batV2Enabled~=nil then batV2Enabled=cfg.batV2Enabled end if cfg.menuScale then _G.AceMenuScale = cfg.menuScale end if cfg.progressBarScale then aceProgressBarScaleValue = cfg.progressBarScale _G.AceProgressBarScale = cfg.progressBarScale end end local function loadConfigState() local cfg=_savedCfg if cfg then if normalBox then normalBox.Text=tostring(NS) end if carryBox then carryBox.Text=tostring(CS) end if laggerBox then laggerBox.Text=tostring(LAGGER_SPEED) end if laggerCarryBox then laggerCarryBox.Text=tostring(LAGGER_CARRY_SPEED) end if autoTPHeightBox then autoTPHeightBox.Text=tostring(autoTPHeight) end if menuScaleBox then menuScaleBox.Text = tostring(_G.AceMenuScale or 1.0) end if progressBarScaleBox then progressBarScaleBox.Text = tostring(aceProgressBarScaleValue) end end if grabRadiusBox then grabRadiusBox.Text = tostring(Steal.StealRadius) end if primeStealRangeBox then primeStealRangeBox.Text = tostring(SemiSteal.STEAL_PRIME_RANGE) end if semiStealRadiusBox then semiStealRadiusBox.Text = tostring(SemiSteal.STEAL_RADIUS) end if updateStealModeButtons then updateStealModeButtons() end updateRadiusDisplay(Steal.StealRadius) applyAceProgressBarScale() task.spawn(function() task.wait(0.15) if cfg then if cfg.antiRagdoll then antiRagdollEnabled=true if setAntiRagVisual then setAntiRagVisual(true) end startAntiRagdoll() end if cfg.autoStealEnabled then Steal.AutoStealEnabled=true if setInstaGrab then setInstaGrab(true) end if _G.AceAutoStealSync then task.defer(_G.AceAutoStealSync) end end if cfg.infiniteJump then infJumpEnabled=true if setInfJumpVisual then setInfJumpVisual(true) end startInfiniteJump() else infJumpEnabled=false if setInfJumpVisual then setInfJumpVisual(false) end stopInfiniteJump() end if cfg.medusaCounter then medusaCounterEnabled=true;if setMedusaVisual then setMedusaVisual(true) end;setupMedusa(LP.Character) end if cfg.batCounter then batCounterEnabled=true;if setBatCounterVisual then setBatCounterVisual(true) end;startBatCounter() end if cfg.laggerMode then laggerToggled=true;speedMode=false;laggerPhase=cfg.laggerCarryMode and 2 or 1;refreshSpeedModeLabel() elseif cfg.carryMode then speedMode=false;toggleCarryMode() end if cfg.autoTPEnabled then autoTPEnabled=true;if setAutoTPVisual then setAutoTPVisual(true) end;startAutoTP() end if setAutoSwingVisual then setAutoSwingVisual(autoSwingEnabled) end if cfg.autoBat then autoBatEnabled=true if autoBatSetVisual then autoBatSetVisual(true) end if _updateMobileAimbot then _updateMobileAimbot(true) end enableAutoBat() end if